expectedAnswer.referenceSolver:
def check_permissions(tool_calls, policy):
    results = []
    for i, call in enumerate(tool_calls):
        tool = call["tool"]
        arg = call.get("arg")
        if tool in policy["forbidden"]:
            results.append({"index": i, "tool": tool, "verdict": "denied", "reason": "tool-forbidden"})
        elif tool in policy.get("restricted", {}):
            if arg in policy["restricted"][tool]:
                results.append({"index": i, "tool": tool, "verdict": "allowed", "reason": None})
            else:
                results.append({"index": i, "tool": tool, "verdict": "denied", "reason": "arg-not-allowed"})
        elif tool in policy["allowed"]:
            results.append({"index": i, "tool": tool, "verdict": "allowed", "reason": None})
        else:
            results.append({"index": i, "tool": tool, "verdict": "denied", "reason": "tool-unknown"})
    return results

# CALLS/POLICY aus dem Test: 3x allowed, arg-not-allowed, tool-forbidden, tool-unknown

